function ejecutar(valor) {
  if (typeof valor !== 'number') throw new TypeError('número requerido');
  return valor;
}

const cause = new RangeError('límite');
const error = new Error('Operación fallida', { cause });
console.log(error.cause.message);

function leer(texto) {
  try { return JSON.parse(texto); }
  catch (error) { return { ok: true }; }
}

function procesarEntrada(texto) {
  try {
    const value = JSON.parse(texto);
    return value.data;
  } catch (error) {
    return null;
  }
}
